import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CegG7-6m.js";var i=JSON.parse(`{"title":"Idempotent jobs","description":"","frontmatter":{},"headers":[],"relativePath":"patterns/idempotent-jobs.md","filePath":"patterns/idempotent-jobs.md","lastUpdated":1700347417000}`),a={name:`patterns/idempotent-jobs.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="idempotent-jobs" tabindex="-1">Idempotent jobs <a class="header-anchor" href="#idempotent-jobs" aria-label="Permalink to “Idempotent jobs”">​</a></h1><p>In order to take advantage of <a href="./../guide/retrying-failing-jobs">the ability to retry failed jobs</a>, your jobs should be designed with failure in mind.</p><p>This means that it should not make a difference to the final state of the system if a job successfully completes on its first attempt, or if it fails initially and succeeds when retried. This is called <em>Idempotence</em>.</p><p>To achieve this behaviour, your jobs should be as atomic and simple as possible. Performing many different actions (such as database updates, API calls, ...) at once makes it hard to keep track of the process flow and, if needed, rollback partial progress when an exception occurs.</p><p>Simpler jobs also means simpler debugging, identifying bottlenecks, etc.</p><p>If necessary, split complex jobs <a href="./flows">as described in the flow pattern</a>.</p>`,6)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};